	Created: Eden
	Date: 20191029
	Task: Migrate PT of Number Games to DCS [RM:#123750]
	DB: DBCust/CustDB
*/

ALTER PROCEDURE [dbo].[Acc_Dep_DynamicCustSetting_09]
	 @recommend INT		
	,@target VARCHAR(20)
	,@PT smallmoney
	,@max_custid INT
AS
BEGIN
	SET NOCOUNT ON
	
	IF (@target = 'REPLICATED' AND @@SERVERNAME IN ('DBCUST','SITDBCUST','DB233','DB230\SQLSERVER2008R2')) RETURN	-- run at all replicated servers
	IF (@target = 'DBCUST' AND @@SERVERNAME NOT IN ('DBCUST','SITDBCUST','DB233','DB230\SQLSERVER2008R2')) RETURN -- run at dbcust only

	--IF dbo.f_CheckRepTable('CustInfo') = 0 RETURN
	--IF dbo.f_CheckRepTable('Dep_CustPTSetting_Agent') = 0 RETURN
	--IF dbo.f_CheckRepTable('Dep_CustPTSetting_Member') = 0 RETURN

	DECLARE @sporttype smallint = 161, @bettype smallint = 81

	DECLARE @mrecommend INT ,@srecommend INT	
	
	SELECT @mrecommend = mrecommend,
		   @srecommend = srecommend
	FROM Custinfo WITH (NOLOCK)
	WHERE custid = @recommend

	CREATE TABLE #MemberTemp(CustID INT PRIMARY KEY CLUSTERED)

	INSERT INTO #MemberTemp (CustID)
	SELECT custid
	FROM Custinfo WITH (NOLOCK)
	WHERE recommend = @recommend AND roleid = 1  AND Enabled = 1 AND custid <= @max_custid

	------------------------------------PT Setting-------------------------------------------------------
	IF NOT EXISTS ( SELECT TOP 1 1 FROM Dep_CustPTSetting_Agent WITH(NOLOCK) WHERE CustID = @srecommend AND sporttype = @sporttype AND bettype = @bettype)	
		INSERT INTO Dep_CustPTSetting_Agent (CustID, SportType, BetType, IsLive, AgentPT, MasterPT, SuperPT)
		SELECT @srecommend, @sporttype AS SportType, @bettype AS BetType, 0 AS IsLive, @PT * 100 AS AgentPT, @PT * 100 AS MasterPT, @PT * 100 AS SuperPT

	IF NOT EXISTS ( SELECT TOP 1 1 FROM Dep_CustPTSetting_Agent WITH(NOLOCK) WHERE CustID = @mrecommend AND sporttype = @sporttype AND bettype = @bettype)	
		INSERT INTO Dep_CustPTSetting_Agent (CustID, SportType, BetType, IsLive, AgentPT, MasterPT, SuperPT)
		SELECT @mrecommend, @sporttype AS SportType, @bettype AS BetType, 0 AS IsLive, 0 AS AgentPT, @PT * 100 AS MasterPT, 0 AS SuperPT
	
	INSERT INTO Dep_CustPTSetting_Agent (CustID, SportType, BetType, IsLive, AgentPT, MasterPT, SuperPT)
	SELECT @recommend, @sporttype AS SportType, @bettype AS BetType, 0 AS IsLive, @PT * 100 AS AgentPT, 0 AS MasterPT, 0 AS SuperPT

	INSERT INTO Dep_CustPTSetting_Member(CustID, SportType, BetType, IsLive, AgentPT, MasterPT, SuperPT)
	SELECT a.CustID, @sporttype AS SportType, @bettype AS BetType, 0 AS IsLive, @PT * 100 AS AgentPT, 0 AS MasterPT, 0 AS SuperPT
	FROM #MemberTemp a

	DROP TABLE #MemberTemp
END
GO

